// ════════════════════════════════════════════════════════════
//  EDIT THESE TWO THINGS
// ════════════════════════════════════════════════════════════
const BUSINESS = 'Your Business Name';

// Each rule: if the customer's message matches `when`, we send `reply`.
// Add as many as you like. Order matters - first match wins.
const RULES = [
  { when: /price|cost|how much|rate/i,     reply: 'Here is our price list: <paste your link>. Anything specific you want quoted?' },
  { when: /hours|open|close|timing/i,      reply: 'We are open Sunday to Thursday, 9am to 6pm.' },
  { when: /location|where|address|map/i,   reply: 'Here is our location: <paste your Google Maps link>.' },
  { when: /deliver|shipping|how long/i,    reply: 'Delivery takes 2 to 3 working days. Free over a certain order value.' },
  { when: /human|agent|call me|speak/i,    reply: 'Got it - a human will get back to you shortly.' }
];

// Used when nothing matches.
const FALLBACK = 'Thanks for your message! We will get back to you shortly.';
// ════════════════════════════════════════════════════════════

const msg  = \$json.body?.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
const text = (msg?.text?.body || '').trim();

const hit = RULES.find(r => r.when.test(text));

return [{ json: {
  to:       msg?.from,
  reply:    hit ? hit.reply : FALLBACK,
  matched:  hit ? String(hit.when) : 'fallback',
  incoming: text,
  business: BUSINESS
}}];
